import re,sys
from lxml import etree
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
doc=etree.parse('/workspace/rl/word/document.xml')
body=doc.getroot().find(W+'body')
def txt(el):
    out=[]
    for n in el.iter():
        if n.tag==W+'t' or n.tag==W+'delText': out.append(n.text or '')
        elif n.tag==W+'tab': out.append('\t')
    return ''.join(out)
def para(p):
    s=[]; changed=False
    for ch in p.iter():
        pass
    def walk(el):
        nonlocal changed
        for c in el:
            t=c.tag
            if t==W+'ins':
                changed=True; s.append('[[INS id=%s by %s: '%(c.get(W+'id'),c.get(W+'author'))+txt(c)+']]')
            elif t==W+'del':
                changed=True; s.append('[[DEL id=%s: '%c.get(W+'id')+txt(c)+']]')
            elif t==W+'r':
                s.append(txt(c))
                if c.find(W+'commentReference') is not None:
                    s.append('{{CMT %s}}'%c.find(W+'commentReference').get(W+'id'))
            elif t==W+'commentRangeStart': s.append('<<C%s:'%c.get(W+'id'))
            elif t==W+'commentRangeEnd': s.append(':C%s>>'%c.get(W+'id'))
            elif t in (W+'hyperlink',W+'smartTag',W+'sdt',W+'sdtContent',W+'fldSimple'): walk(c)
            elif t==W+'pPr':
                rp=c.find(W+'rPr')
                if rp is not None and (rp.find(W+'ins') is not None or rp.find(W+'del') is not None):
                    changed=True; s.append('[[PARAMARK-CHANGE]]')
    walk(p)
    return ''.join(s),changed
mode=sys.argv[1]
for el in body.iter(W+'p'):
    t,c=para(el)
    if mode=='all' or c or '<<C' in t: print(('** ' if c else '   ')+t)
