from docx import Document
from docx.shared import Pt, RGBColor, Inches, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.enum.section import WD_ORIENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

COL={'RED':'F4C7C3','YELLOW':'FFF2CC','GREEN':'D9EAD3','HDR':'1F3864','GREY':'EDEDED'}

def shade(cell,hexcol):
    tcPr=cell._tc.get_or_add_tcPr()
    s=OxmlElement('w:shd'); s.set(qn('w:val'),'clear'); s.set(qn('w:color'),'auto'); s.set(qn('w:fill'),hexcol); tcPr.append(s)

def set_cell(cell,text,bold=False,size=8.5,color=None,italic=False):
    cell.text=''
    p=cell.paragraphs[0]
    parts=text.split('\n')
    for i,part in enumerate(parts):
        if i>0: p=cell.add_paragraph()
        p.paragraph_format.space_after=Pt(1); p.paragraph_format.space_before=Pt(0)
        add_rich(p,part,size=size,bold=bold,color=color,italic=italic)

def add_rich(p,text,size=10.5,bold=False,color=None,italic=False):
    # **bold** markup support
    segs=text.split('**')
    for i,s in enumerate(segs):
        if not s: continue
        r=p.add_run(s); r.font.size=Pt(size); r.bold=bold or (i%2==1); r.italic=italic
        if color: r.font.color.rgb=RGBColor.from_string(color)
    return p

def table(doc,headers,rows,widths,classcol=None,size=8.5):
    t=doc.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    t.autofit=False
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; set_cell(c,h,bold=True,size=size,color='FFFFFF'); shade(c,COL['HDR'])
    # repeat header
    trPr=t.rows[0]._tr.get_or_add_trPr(); th=OxmlElement('w:tblHeader'); th.set(qn('w:val'),'true'); trPr.append(th)
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row):
            set_cell(cells[i],str(v),size=size)
        if classcol is not None:
            v=str(row[classcol]).upper()
            for k in ('RED','YELLOW','GREEN'):
                if v.startswith(k): shade(cells[classcol],COL[k])
    for row in t.rows:
        for i,w in enumerate(widths):
            row.cells[i].width=Inches(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def setup(doc):
    st=doc.styles['Normal']; st.font.name='Calibri'; st.font.size=Pt(10.5)
    st.element.rPr.rFonts.set(qn('w:eastAsia'),'Calibri')
    for n,sz in (('Heading 1',15),('Heading 2',12.5),('Heading 3',11)):
        h=doc.styles[n]; h.font.name='Calibri'; h.font.size=Pt(sz); h.font.color.rgb=RGBColor.from_string('1F3864')
    sec=doc.sections[0]
    sec.page_width=Inches(11); sec.page_height=Inches(8.5); sec.orientation=WD_ORIENT.LANDSCAPE
    for m in ('left_margin','right_margin'): setattr(sec,m,Inches(0.75))
    sec.top_margin=Inches(0.7); sec.bottom_margin=Inches(0.7)
    hp=sec.header.paragraphs[0]; hp.text='PRIVILEGED & CONFIDENTIAL - ATTORNEY-CLIENT COMMUNICATION / ATTORNEY WORK PRODUCT - DO NOT FORWARD TO COUNTERPARTY'
    hp.runs[0].font.size=Pt(8); hp.alignment=WD_ALIGN_PARAGRAPH.CENTER
    fp=sec.footer.paragraphs[0]; fp.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=fp.add_run('Stratton Health / CloudNest DPA - Deviation Report - Whitfield & Crane LLP - Page '); r.font.size=Pt(8)
    for code in ('PAGE',):
        r2=fp.add_run(); r2.font.size=Pt(8)
        f1=OxmlElement('w:fldChar'); f1.set(qn('w:fldCharType'),'begin')
        it=OxmlElement('w:instrText'); it.set(qn('xml:space'),'preserve'); it.text=code
        f2=OxmlElement('w:fldChar'); f2.set(qn('w:fldCharType'),'end')
        r2._r.append(f1); r2._r.append(it); r2._r.append(f2)

def para(doc,text,size=10.5,bold=False,italic=False,after=4,style=None):
    p=doc.add_paragraph(style=style) if style else doc.add_paragraph()
    p.paragraph_format.space_after=Pt(after)
    add_rich(p,text,size=size,bold=bold,italic=italic); return p

def bullet(doc,text,size=10.5,level=0):
    p=doc.add_paragraph(style='List Bullet' if level==0 else 'List Bullet 2')
    p.paragraph_format.space_after=Pt(2)
    add_rich(p,text,size=size); return p

def num(doc,text,size=10.5):
    p=doc.add_paragraph(style='List Number'); p.paragraph_format.space_after=Pt(2)
    add_rich(p,text,size=size); return p
